using UnscRelay.Core;
internal static class ManagedFileDeletionChecks
{
 public static int Run(){if(!OperatingSystem.IsWindows())throw new PlatformNotSupportedException("This Windows deletion test requires Windows.");var root=Directory.CreateTempSubdirectory("relay-managed-delete-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS managed file deletion: "+label);}try{var path=Path.Combine(root.FullName,"owned.bin");File.WriteAllText(path,"owned fixture");using(var held=new ManagedFileDeletion(path)){using var reader=new StreamReader(held.Content,leaveOpen:true);Check(reader.ReadToEnd()=="owned fixture","deletion opens the exact authorized file without changing bytes");try{File.WriteAllText(path,"changed fixture");throw new Exception("Concurrent write accepted");}catch(IOException){Check(true,"open deletion handle excludes concurrent writers");}try{File.Move(path,path+".moved");throw new Exception("Concurrent rename accepted");}catch(IOException){Check(true,"open deletion handle excludes replacement");}held.Delete();}Check(!File.Exists(path),"only the verified handle is deleted after close");var outside=Path.Combine(root.FullName,"outside.bin");File.WriteAllText(outside,"sentinel");File.CreateSymbolicLink(path,outside);try{using var linked=new ManagedFileDeletion(path);linked.Delete();throw new Exception("Linked target deleted");}catch(IOException){Check(File.ReadAllText(outside)=="sentinel","symbolic link is refused without deleting its target");}using(var ownLink=new ManagedFileDeletion(path,true)){ownLink.Delete();}Check(!File.Exists(path)&&File.ReadAllText(outside)=="sentinel","explicit link removal deletes only the verified link object");var folder=Directory.CreateDirectory(Path.Combine(root.FullName,"linked"));Directory.Delete(folder.FullName);Directory.CreateSymbolicLink(folder.FullName,root.FullName);try{using var linked=new ManagedFileDeletion(Path.Combine(folder.FullName,"outside.bin"));linked.Delete();throw new Exception("Linked parent deleted");}catch(IOException){Check(File.ReadAllText(outside)=="sentinel","linked parent is refused before any deletion");}using(var ownLink=new ManagedFileDeletion(folder.FullName,true)){ownLink.Delete();}Check(!Directory.Exists(folder.FullName)&&File.ReadAllText(outside)=="sentinel","directory link removal never traverses or deletes target contents");Console.WriteLine("Managed file deletion checks: "+count);return 0;}finally{root.Delete(true);}}
}
